/* Browser gestures must not cancel pointer-driven gameplay. Keep this off
   html/body and reading dialogs: users can still zoom instructions and results. */
[data-game-gesture-surface]:not([data-game-gesture-overlays]) {
  touch-action: none;
}
/* Games may have nested results dialogs or inline pause/help panels. When open, the parent
   must also allow zoom, since a child's touch-action cannot override an ancestor. */
[data-game-gesture-surface][data-game-gesture-overlays]:not(:has(dialog[open], [data-game-gesture-reading]:not([hidden]):not(.hidden))) {
  touch-action: none;
}

// Keep browser zoom gestures out of the play surface without owning game input.
// Pointer Events, click activation, keyboard input and multi-finger controls remain
// with each game. Never synthesize clicks or stop event propagation here.
const installed = new WeakMap();
const nativeControl = 'button,a,input,textarea,select,summary,label,[contenteditable],[role="button"]';
const readingRegion = 'dialog,[data-game-gesture-reading]';
const prevent = event => { if (event.cancelable) event.preventDefault(); };

export function protectGameGestures(surface) {
  if (installed.has(surface)) return installed.get(surface);
  const listeners = [];
  let start = null;
  let lastTap = null;
  const isReading = target => Boolean(target?.closest?.(readingRegion));
  const listen = (type, handler) => {
    surface.addEventListener(type, handler, {passive: false});
    listeners.push([type, handler]);
  };
  const reset = () => { start = null; lastTap = null; };
  const guardGesture = event => {
    if (!isReading(event.target)) prevent(event);
  };
  // Safari's GestureEvents need an explicit fallback as well as touch-action.
  for (const type of ['gesturestart', 'gesturechange', 'dblclick']) listen(type, guardGesture);
  listen('touchstart', event => {
    if (isReading(event.target)) { reset(); return; }
    if (event.touches?.length > 1) { reset(); prevent(event); return; }
    const finger = event.touches?.[0];
    start = finger ? {x: finger.clientX, y: finger.clientY, at: event.timeStamp} : null;
  });
  listen('touchmove', event => {
    if (isReading(event.target)) return;
    if (event.touches?.length > 1) { reset(); prevent(event); return; }
    const finger = event.touches?.[0];
    if (start && finger && Math.hypot(finger.clientX - start.x, finger.clientY - start.y) > 24) reset();
  });
  listen('touchend', event => {
    const finger = event.changedTouches?.[0];
    // Preserve real native clicks on buttons/links, including user activation for
    // sharing. CSS handles their zoom policy; this fallback is for scenery taps.
    if (isReading(event.target) || event.target?.closest?.(nativeControl) ||
        event.touches?.length || !start || !finger || event.timeStamp - start.at > 300) {
      reset(); return;
    }
    const tap = {x: finger.clientX, y: finger.clientY, at: event.timeStamp};
    const stationary = Math.hypot(tap.x - start.x, tap.y - start.y) <= 24;
    if (stationary && lastTap && tap.at - lastTap.at >= 0 && tap.at - lastTap.at < 320 &&
        Math.hypot(tap.x - lastTap.x, tap.y - lastTap.y) <= 24) prevent(event);
    lastTap = stationary ? tap : null;
    start = null;
  });
  listen('touchcancel', reset);
  const dispose = () => {
    for (const [type, handler] of listeners) surface.removeEventListener(type, handler);
    reset();
    installed.delete(surface);
  };
  installed.set(surface, dispose);
  return dispose;
}

export function installGameGestures(root = document) {
  return [...root.querySelectorAll('[data-game-gesture-surface]')].map(protectGameGestures);
}
if (typeof document !== 'undefined') installGameGestures(document);

// Historical views reverse only this exact, independently pinned installation patch.
// Runtime and behavior tests continue to read live files directly.
import {readFileSync as actual,readdirSync as actualDirectory} from 'node:fs';
import {createHash} from 'node:crypto';
import {fileURLToPath} from 'node:url';
import {resolve,relative,sep,isAbsolute} from 'node:path';
import assert from 'node:assert/strict';
const root=fileURLToPath(new URL('../../',import.meta.url));
export const sha256=b=>createHash('sha256').update(b).digest('hex');
export const gitBlob=b=>createHash('sha1').update(`blob ${b.length}\0`).update(b).digest('hex');
const baselineBytes=actual(new URL('../../docs/app-icons-completion/BASELINE.json',import.meta.url));
assert.equal(sha256(baselineBytes),'215c57b5e09a0ab655734c9e2c24de168eb07f4aebb6c77f9d8670b2e4f9ee2c','immutable icon parent inventory');
export const baseline=JSON.parse(baselineBytes);
const previous=new Map(baseline.files.map(f=>[f.path,f.gitBlob]));
export function verifyBase(b){
 assert.equal(b.baseCommit,'0b357ad7474687a543533412d8b5f5c3f218fe80');assert.equal(b.baseTree,'0fc0f9ae615ab396303fd427d68c31fa13bfd59b');assert.deepEqual(b,baseline);
 const tree={};for(const f of b.files){let d=tree;const p=f.path.split('/');for(const n of p.slice(0,-1))d=d[n]??={};assert.ok(!d[p.at(-1)],'duplicate parent path');d[p.at(-1)]={file:f};}
 function digest(d){const entries=Object.entries(d).sort(([a,x],[b,y])=>Buffer.compare(Buffer.from(a+(x.file?'':'/')),Buffer.from(b+(y.file?'':'/'))));const bytes=Buffer.concat(entries.map(([n,x])=>Buffer.concat([Buffer.from(`${x.file?x.file.mode:'40000'} ${n}\0`),Buffer.from(x.file?x.file.gitBlob:digest(x),'hex')])));return createHash('sha1').update(`tree ${bytes.length}\0`).update(bytes).digest('hex');}
 assert.equal(digest(tree),b.baseTree);return true;
}
verifyBase(baseline);
const manifestPath='docs/app-icons-completion/MANIFEST.json';
export function manifest(){return JSON.parse(actual(new URL('../../'+manifestPath,import.meta.url),'utf8'));}
export function validate(m){
 assert.equal(m.baseCommit,baseline.baseCommit);assert.equal(m.baseTree,baseline.baseTree);
 assert.deepEqual(m.files.map(f=>f.path).sort(),baseline.modifiedPaths);
 assert.deepEqual([...m.addedPaths].sort(),baseline.addedPaths);
 assert.deepEqual(m.addedFiles.map(f=>f.path).sort(),baseline.addedPaths.filter(p=>p!==manifestPath));
 assert.deepEqual(m.addedPublicPaths,baseline.addedPaths.filter(p=>p.startsWith('public/')).map(p=>p.slice(7)));
 for(const f of m.files){assert.equal(typeof f.beforeText,'string');const bytes=Buffer.from(f.beforeText);assert.equal(f.beforeGitBlob,previous.get(f.path));assert.equal(gitBlob(bytes),f.beforeGitBlob);assert.equal(sha256(bytes),f.beforeSha256);assert.match(f.gitBlob,/^[a-f0-9]{40}$/);assert.match(f.sha256,/^[a-f0-9]{64}$/);
  if(f.path.startsWith('public/')){assert.equal(f.kind,'head-metadata');assert.equal(f.beforeText.split('</head>').length,2);assert.equal(sha256(Buffer.from(f.beforeText.split('</head>')[1])),f.bodySha256);assert.equal(typeof f.block,'string');assert.ok(f.block.startsWith('<!-- app-icons-completion:start -->\n'));assert.ok(f.block.endsWith('<!-- app-icons-completion:end -->\n'));assert.doesNotMatch(f.beforeText,/app-icons-completion:/);}
 }
 for(const f of m.addedFiles){assert.match(f.gitBlob,/^[a-f0-9]{40}$/);assert.match(f.sha256,/^[a-f0-9]{64}$/);}
 return m;
}
export function iconsParentBytes(path,bytes,m=manifest()){
 validate(m);bytes=Buffer.from(bytes);const f=m.files.find(f=>f.path===path);if(!f)return bytes;
 // Accept an already reconstructed parent only when its bytes match the pin.
 const before=Buffer.from(f.beforeText);if(bytes.equals(before))return before;
 assert.equal(gitBlob(bytes),f.gitBlob,path+' icon live drift');assert.equal(sha256(bytes),f.sha256,path+' icon live SHA256 drift');
 if(f.kind==='head-metadata'){
  const text=bytes.toString();assert.equal(text.split(f.block).length,2,'exactly one icon block');assert.ok(text.includes(f.block+'</head>'),'icon block immediately before head close');
  const reversed=Buffer.from(text.replace(f.block,''));assert.ok(reversed.equals(before),path+' metadata-only boundary');return reversed;
 }
 return before;
}
export function readBeforeIcons(file,options){
 const absolute=file instanceof URL?fileURLToPath(file):resolve(String(file)),path=relative(root,absolute).split(sep).join('/');
 if(!path||path==='..'||path.startsWith('../')||isAbsolute(path))return actual(file,options);
 const encoding=typeof options==='string'?options:options?.encoding;
 const bytes=actual(file,typeof options==='object'&&options?{...options,encoding:null}:undefined);
 const before=baseline.modifiedPaths.includes(path)?iconsParentBytes(path,bytes):bytes;return encoding?before.toString(encoding):before;
}
export function inventoryBeforeIcons(paths,{read=p=>actual(new URL('../../'+p,import.meta.url)),runtimeOnly=false}={}){
 assert.equal(new Set(paths).size,paths.length,'duplicate icon inventory');const m=validate(manifest());
 if(!paths.some(p=>m.addedPaths.includes(p)))return paths;
 // Older runtime inventory callers omit runtimeOnly at intervening boundaries.
 const runtime=p=>/^(public|worker|src|config)\//.test(p);
 const onlyRuntime=runtimeOnly||paths.every(runtime),additions=m.addedPaths.filter(p=>!onlyRuntime||runtime(p));
 for(const p of additions)assert.equal(paths.filter(x=>x===p).length,1,p+' icon addition must appear once');
 for(const f of [...m.files,...m.addedFiles].filter(f=>!onlyRuntime||runtime(f.path))){const bytes=read(f.path);assert.equal(gitBlob(bytes),f.gitBlob,f.path+' icon inventory live drift');assert.equal(sha256(bytes),f.sha256,f.path+' icon inventory SHA256 drift');}
 return paths.filter(p=>!additions.includes(p));
}

// Only old Fast Hands directory-inventory assertions use this narrow view.
// Unknown files remain visible; each excluded manifest must exist and match its pin.
export function entriesBeforeIcons(directory,entries,{read=p=>actual(new URL('../../'+p,import.meta.url))}={}){
 const absolute=directory instanceof URL?fileURLToPath(directory):resolve(String(directory));
 const path=relative(root,absolute).split(sep).join('/');
 if(path!=='public/games/fast-hands')return entries;
 const m=validate(manifest()),additions=m.addedFiles.filter(f=>f.path.startsWith(path+'/')&&!f.path.slice(path.length+1).includes('/'));
 assert.deepEqual(additions.map(f=>f.path.slice(path.length+1)).sort(),['catch.webmanifest','duel.webmanifest','manifest.webmanifest']);
 const names=entries.map(e=>typeof e==='string'?e:Buffer.isBuffer(e)?e.toString():e.name);
 assert.equal(new Set(names).size,names.length,'duplicate historical directory entry');
 for(const f of additions){const name=f.path.slice(path.length+1);assert.equal(names.filter(n=>n===name).length,1,name+' manifest must exist before historical exclusion');const bytes=read(f.path);assert.equal(gitBlob(bytes),f.gitBlob,f.path+' manifest drift');assert.equal(sha256(bytes),f.sha256,f.path+' manifest SHA256 drift');}
 return entries.filter((e,i)=>!additions.some(f=>f.path===path+'/'+names[i]));
}
export function readdirBeforeIcons(directory,options){return entriesBeforeIcons(directory,actualDirectory(directory,options));}

import test from 'node:test';
import assert from 'node:assert/strict';
import {readFile} from 'node:fs/promises';
import {JSDOM} from 'jsdom';
let api={};try{api=await import('../public/games/shared/mobile-gestures.mjs');}catch(e){if(e.code!=='ERR_MODULE_NOT_FOUND')throw e;}
const entries=["beer-slide/index","courtesy-contest/index","discus/index","fast-hands-test/index","fast-hands/catch","fast-hands/duel","fast-hands/index","high-jump/index","hurdles/index","javelin/index","long-jump/index","pole-vault/index","reaction-rod/index","run-1500m/index","run-400m/index","shot-put/index","sprint-100m/index","tower-climb/index"];
function setup(){assert.equal(typeof api.protectGameGestures,'function','A shared native zoom guard is required');const dom=new JSDOM('<main><section data-game-gesture-surface><canvas></canvas><button>Play</button></section><dialog open><p>Read settings</p><input></dialog></main>');const d=dom.window.document,surface=d.querySelector('section'),canvas=d.querySelector('canvas'),button=d.querySelector('button');const dispose=api.protectGameGestures(surface);return{dom,d,surface,canvas,button,dispose};}
function send(dom,target,type,props={}){const e=new dom.window.Event(type,{bubbles:true,cancelable:true});for(const[k,v]of Object.entries(props))Object.defineProperty(e,k,{value:v});target.dispatchEvent(e);return e;}
const touch=(target,x=20,y=20,id=1)=>({target,clientX:x,clientY:y,identifier:id});
function tap(ctx,target,time,x=20){const t=touch(target,x);send(ctx.dom,target,'touchstart',{touches:[t],changedTouches:[t],timeStamp:time});return send(ctx.dom,target,'touchend',{touches:[],changedTouches:[t],timeStamp:time+25});}
test('all preview game entries load the shared guard and stylesheet without viewport scaling restrictions',async()=>{
 for(const entry of entries){const d=new JSDOM(await readFile(new URL(`../public/games/${entry}.html`,import.meta.url),'utf8')).window.document;
 assert.ok(d.querySelector('script[type="module"][src="../shared/mobile-gestures.mjs"]'),entry);
 assert.ok(d.querySelector('link[rel="stylesheet"][href="../shared/mobile-gestures.css"]'),entry);
 assert.ok(d.querySelector('[data-game-gesture-surface]'),entry);
 assert.doesNotMatch(d.querySelector('meta[name="viewport"]').content,/user-scalable\s*=\s*no|maximum-scale/i,entry);
 for(const dialog of d.querySelectorAll('dialog')){const ancestor=dialog.closest('[data-game-gesture-surface]');if(ancestor)assert.ok(ancestor.hasAttribute('data-game-gesture-overlays'),`${entry}: nested dialog must release the ancestor gesture lock`);}
 assert.ok(d.querySelector('main[data-game-gesture-surface]'),`${entry}: protect gaps between scene and controls`);
 for(const el of d.querySelectorAll('[data-game-gesture-surface]'))assert.ok(!['HTML','BODY'].includes(el.tagName),entry);
 }
});
test('native double tap and Safari pinch defaults cancel only on gameplay, not reading dialogs',()=>{
 const ctx=setup();for(const type of ['dblclick','gesturestart','gesturechange']){assert.equal(send(ctx.dom,ctx.canvas,type).defaultPrevented,true,type);assert.equal(send(ctx.dom,ctx.d.querySelector('dialog p'),type).defaultPrevented,false,type);}
 const a=touch(ctx.canvas),b=touch(ctx.canvas,60,20,2);
 assert.equal(send(ctx.dom,ctx.canvas,'touchstart',{touches:[a,b],changedTouches:[b]}).defaultPrevented,true);
 assert.equal(send(ctx.dom,ctx.canvas,'touchmove',{touches:[a,b],changedTouches:[b]}).defaultPrevented,true);
 assert.equal(send(ctx.dom,ctx.d.querySelector('dialog p'),'touchmove',{touches:[a,b]}).defaultPrevented,false);
});
test('legacy double-tap fallback does not consume the first tap, long press, movement or ordinary button clicks',()=>{
 const ctx=setup();assert.equal(tap(ctx,ctx.canvas,100).defaultPrevented,false);assert.equal(tap(ctx,ctx.canvas,250).defaultPrevented,true);
 assert.equal(tap(ctx,ctx.canvas,1000).defaultPrevented,false);assert.equal(tap(ctx,ctx.canvas,1150,120).defaultPrevented,false);
 assert.equal(tap(ctx,ctx.button,1500).defaultPrevented,false);assert.equal(tap(ctx,ctx.button,1600).defaultPrevented,false);
 let clicks=0;ctx.button.addEventListener('click',()=>clicks++);send(ctx.dom,ctx.button,'click');send(ctx.dom,ctx.button,'click');assert.equal(clicks,2);
 const t=touch(ctx.canvas);send(ctx.dom,ctx.canvas,'touchstart',{touches:[t],timeStamp:2000});assert.equal(send(ctx.dom,ctx.canvas,'touchend',{touches:[],changedTouches:[t],timeStamp:2700}).defaultPrevented,false);
});
test('game pointer movement, four simultaneous limb inputs, release/cancel, and keyboard remain unmodified',()=>{
 const ctx=setup(),held=new Set();let bubbled=0;ctx.d.addEventListener('pointerdown',()=>bubbled++);ctx.canvas.addEventListener('pointerdown',e=>held.add(e.pointerId));ctx.canvas.addEventListener('pointerup',e=>held.delete(e.pointerId));ctx.canvas.addEventListener('pointercancel',e=>held.delete(e.pointerId));
 for(let id=1;id<=4;id++)assert.equal(send(ctx.dom,ctx.canvas,'pointerdown',{pointerId:id,pointerType:'touch',isPrimary:id===1}).defaultPrevented,false);
 assert.equal(held.size,4);assert.equal(bubbled,4);
 for(const type of ['pointermove','lostpointercapture','keydown','keyup','click'])assert.equal(send(ctx.dom,ctx.canvas,type).defaultPrevented,false,type);
 send(ctx.dom,ctx.canvas,'pointercancel',{pointerId:2});send(ctx.dom,ctx.canvas,'pointerup',{pointerId:1});assert.deepEqual([...held],[3,4]);
});
test('installation is idempotent and cleanup restores defaults after remount',()=>{
 const ctx=setup();assert.equal(api.protectGameGestures(ctx.surface),ctx.dispose);ctx.dispose();assert.equal(send(ctx.dom,ctx.canvas,'gesturestart').defaultPrevented,false);api.protectGameGestures(ctx.surface);assert.equal(send(ctx.dom,ctx.canvas,'gesturestart').defaultPrevented,true);
});
test('CSS protects marked gameplay surfaces only and never disables reading zoom globally',async()=>{
 const css=await readFile(new URL('../public/games/shared/mobile-gestures.css',import.meta.url),'utf8');assert.match(css,/\[data-game-gesture-surface\][^{]*\{[^}]*touch-action:\s*none/);assert.doesNotMatch(css,/(?:^|\})\s*(?:html|body|\*)\s*\{/);assert.doesNotMatch(css,/-webkit-text-size-adjust:\s*none/);
});

test('nested reading dialogs and inline pause panels bypass every native-gesture fallback',()=>{
 const ctx=setup();ctx.surface.append(ctx.d.querySelector('dialog'));const panel=ctx.d.createElement('div');panel.setAttribute('data-game-gesture-reading','');ctx.surface.append(panel);
 for(const target of [ctx.d.querySelector('dialog p'),panel])for(const type of ['gesturestart','gesturechange','dblclick','touchstart','touchmove','touchend'])assert.equal(send(ctx.dom,target,type,{touches:[touch(target),touch(target,60,20,2)]}).defaultPrevented,false,type);
});


test('class-hidden courtesy pause overlays do not release the active game touch lock',async()=>{
 const css=await readFile(new URL('../public/games/shared/mobile-gestures.css',import.meta.url),'utf8');
 assert.ok(css.includes('[data-game-gesture-reading]:not([hidden]):not(.hidden)'), 'both hidden attribute and hidden class must keep gameplay protected');
});
